#!/usr/bin/env bash
# Deploy codex-sidecar as a new generation and cut over live (credentials come from the fleet-env store, or from a user env file with --env-file).
# Build, write a generation directory, start codex-sidecar@<activation>, verify it by its /healthz body, switch the boot generation, retire the old one (SIGUSR1) and confirm it stopped accepting, prune. A test home (--home other than $HOME) never touches systemd.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'sidecar/install.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'install.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -euo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
TEMPLATE="$SCRIPT_DIR/codex-sidecar@.service.in"
STATIC_UNITS="codex-sidecar.socket codex-sidecar-docker0.socket codex-sidecar-hold.service"
LEGACY_UNIT="codex-sidecar.service"
PERSONAS_ARG="${SIDECAR_PERSONAS:-codex}"
ENV_FILE_ARG=""
ROLLBACK=0
# The loopback listen address the socket unit owns (codex-sidecar.socket ListenStream=).
HEALTH_URL="${SIDECAR_HEALTH_URL:-http://127.0.0.1:4877/healthz}"
VERIFY_TRIES="${SIDECAR_VERIFY_TRIES:-60}"
RETIRE_ACK_TRIES="${SIDECAR_RETIRE_ACK_TRIES:-150}"

INSTALL_HOME="${SIDECAR_INSTALL_HOME:-$HOME}"
RUST_BIN="${SIDECAR_RUST_BIN:-}"

# Default mode (no --env-file): the fleet-env store. The unit reads the tmpfs projection
# %t/fleet-env/codex-sidecar.env, ordered after fleet-env-project.service. The key lives only
# in the canonical store (no env file is created or touched, no key is ever printed). A missing
# fleet-env binary (resolved through PATH) or projection fails loudly -- never a silent fallback.
FLEET_ENV="${FLEET_ENV_BIN:-fleet-env}"

usage() {
  cat <<'USAGE'
usage: install.sh [--personas <a,b>] [--env-file <path>] [--home <dir>] [--rust-bin <path>]
                  [--rollback]

  Deploys a new generation and cuts over live, end to end:
   1. builds rs/ in release from this checkout (or takes --rust-bin);
   2. writes the generation directory
      <home>/.local/lib/codex-sidecar/generations/<activation>/ (the binary plus
      preamble.txt and thread-config.json, which the binary reads beside itself);
   3. renders codex-sidecar@.service, codex-sidecar.socket,
      codex-sidecar-docker0.socket and codex-sidecar-hold.service;
   4. (real home) migrates a legacy codex-sidecar.service (stop-then-start, once),
      starts the sockets, starts codex-sidecar@<activation>, polls /healthz until that
      activation id answers; a failed verify retires the new generation and leaves the
      old one serving;
   5. enables the new generation as the boot generation, sends every older generation
      SIGUSR1 (retire) and waits for its acknowledgment (StatusText "retiring", or the
      unit already gone);
   6. keeps the current and previous generation directories, prunes the rest.
  The activation id is minted per run (UTC timestamp + random suffix), never the build id.
  When the old generation refuses the projected key, the switch is reported as a key
  rotation (a short failure window), not a zero-failure cutover.

  --personas <a,b>  Comma-separated personas to serve (also SIDECAR_PERSONAS; default
                    "codex"). "codex" is the stock binary with CODEX_HOME ~/.codex; any
                    other persona must be named codex-<name>, be an executable of that
                    name on PATH (a wrapper that sets CODEX_HOME to ~/.codex-<name>), and
                    gets %h/.codex-<name> as a writable path in the unit.
  --env-file <path> Read SIDECAR_KEY (and any other sidecar env) from this file instead of
                    the fleet-env store: an absolute path to a regular file, mode 0600,
                    containing a non-empty SIDECAR_KEY=. The unit's EnvironmentFile= points
                    at it. Without this flag the fleet-env store is used (binary resolved
                    through PATH, override with FLEET_ENV_BIN) and a missing binary or
                    projection fails loudly; there is no silent fallback either way.
  --home <dir>      Install under <dir> instead of $HOME (also SIDECAR_INSTALL_HOME).
                    With a non-default home no systemctl/loginctl/curl call is made
                    (test/dry mode): only the files are written.
  --rust-bin <path> Install this prebuilt binary instead of building
                    (also SIDECAR_RUST_BIN; tests use a stub).
  --rollback        Start a new generation from the previous generation's directory
                    (binary and pinned files as they were); no build.
USAGE
}

die() { printf 'install.sh: %s\n' "$*" >&2; exit 1; }

# shellcheck source=/dev/null
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../scripts/lib/build-id.sh"
build_flags "${BASH_SOURCE[0]}" "$@"

while [ $# -gt 0 ]; do
  case "$1" in
    --home)
      [ $# -ge 2 ] || die "--home requires a directory argument"
      INSTALL_HOME="$2"
      shift 2
      ;;
    --home=*)
      INSTALL_HOME="${1#--home=}"
      shift
      ;;
    --rust-bin)
      [ $# -ge 2 ] || die "--rust-bin requires a path argument"
      RUST_BIN="$2"
      shift 2
      ;;
    --rust-bin=*)
      RUST_BIN="${1#--rust-bin=}"
      shift
      ;;
    --personas)
      [ $# -ge 2 ] || die "--personas requires a comma-separated list"
      PERSONAS_ARG="$2"
      shift 2
      ;;
    --personas=*)
      PERSONAS_ARG="${1#--personas=}"
      shift
      ;;
    --env-file)
      [ $# -ge 2 ] || die "--env-file requires a path argument"
      ENV_FILE_ARG="$2"
      shift 2
      ;;
    --env-file=*)
      ENV_FILE_ARG="${1#--env-file=}"
      shift
      ;;
    --rollback) ROLLBACK=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) usage >&2; die "unknown argument: $1" ;;
  esac
done

[ -n "$INSTALL_HOME" ] || die "install home resolves to an empty path"
[ -f "$TEMPLATE" ]   || die "missing unit template: $TEMPLATE"
[ -z "$RUST_BIN" ] || [ -x "$RUST_BIN" ] || die "--rust-bin is not an executable file: $RUST_BIN"
[ "$ROLLBACK" -eq 0 ] || [ -z "$RUST_BIN" ] || die "--rollback takes the previous generation's binary; drop --rust-bin"

# --- personas -------------------------------------------------------------------
PERSONAS=()
RW_PATHS=""
IFS=',' read -r -a _raw_personas <<< "$PERSONAS_ARG"
for persona in "${_raw_personas[@]}"; do
  persona="${persona#"${persona%%[![:space:]]*}"}"
  persona="${persona%"${persona##*[![:space:]]}"}"
  [ -n "$persona" ] || continue
  case "$persona" in
    codex) rw="%h/.codex" ;;
    codex-*)
      case "${persona#codex-}" in
        *[!A-Za-z0-9._-]*|[.-]*) die "invalid persona name: $persona" ;;
      esac
      rw="%h/.$persona"
      ;;
    *) die "invalid persona '$persona': must be 'codex' or 'codex-<name>'" ;;
  esac
  for seen in "${PERSONAS[@]+"${PERSONAS[@]}"}"; do
    [ "$seen" != "$persona" ] || die "duplicate persona: $persona"
  done
  PERSONAS+=("$persona")
  RW_PATHS="${RW_PATHS:+$RW_PATHS }$rw"
done
[ "${#PERSONAS[@]}" -gt 0 ] || die "no personas given (--personas / SIDECAR_PERSONAS is empty)"
PERSONAS_VALUE="$(IFS=,; printf '%s' "${PERSONAS[*]}")"

# --- credential source ------------------------------------------------------------
if [ -n "$ENV_FILE_ARG" ]; then
  case "$ENV_FILE_ARG" in /*) ;; *) die "--env-file must be an absolute path: $ENV_FILE_ARG" ;; esac
  case "$ENV_FILE_ARG" in *[!A-Za-z0-9._/@:+,=%-]*) die "--env-file path has unsupported characters (use letters, digits and ._/@:+,=%-): $ENV_FILE_ARG" ;; esac
  [ -f "$ENV_FILE_ARG" ] || die "--env-file is not a regular file: $ENV_FILE_ARG"
  [ "$(stat -c %a -- "$ENV_FILE_ARG")" = "600" ] || die "--env-file must have mode 0600 (it holds the sidecar key): $ENV_FILE_ARG"
  grep -q '^SIDECAR_KEY=.' -- "$ENV_FILE_ARG" || die "--env-file has no non-empty SIDECAR_KEY= line: $ENV_FILE_ARG"
else
  FLEET_ENV="$(command -v -- "$FLEET_ENV" || true)"
  [ -n "$FLEET_ENV" ] || die "fleet-env binary '${FLEET_ENV_BIN:-fleet-env}' not found on PATH; refusing to install without the credential store (pass --env-file <path> to use a key file instead)"
  [ -x "$FLEET_ENV" ] || die "fleet-env at $FLEET_ENV is not executable"
  # The key is read only through the canonical store (`fleet-env run sidecar-install`), and
  # only tested for presence -- never printed, never written to a file here. Checked before
  # the build and before any write, like the --env-file branch.
  # shellcheck disable=SC2016  # expanded by the child shell, not here
  "$FLEET_ENV" run sidecar-install -- bash -c '[ -n "${CODEX_SIDECAR_KEY:-}" ]' \
    || die "CODEX_SIDECAR_KEY is not available from the fleet-env store (fleet-env check)"
  projection="$("$FLEET_ENV" path codex-sidecar)" || die "fleet-env path codex-sidecar failed"
  [ -f "$projection" ] || die "$projection is missing; run fleet-env project (or install fleet-env-project.service)"
fi

REAL_HOME=0
if [ "$INSTALL_HOME" = "${HOME:-}" ]; then
  REAL_HOME=1
fi

# --- resolve the executables the unit needs by absolute path ------------------
# The systemd --user PATH can differ from the login PATH (for example it lacks ~/.local/bin),
# so the persona executables' dirs are baked into the unit absolutely.
WRAPPER_DIR=""
for persona in "${PERSONAS[@]}"; do
  wrapper="$(command -v "$persona" || true)"
  [ -n "$wrapper" ] || die "persona wrapper '$persona' not found on PATH"
  case "$wrapper" in /*) ;; *) die "wrapper '$persona' resolved to a non-absolute path: $wrapper" ;; esac
  # PATH-visible dir, not the symlink target: the unit needs the name the
  # sidecar spawns ("<persona> app-server") to be findable on the unit PATH.
  dir="$(dirname -- "$wrapper")"
  if [ -z "$WRAPPER_DIR" ]; then
    WRAPPER_DIR="$dir"
  elif [ "$WRAPPER_DIR" != "$dir" ]; then
    WRAPPER_DIR="$WRAPPER_DIR:$dir"
  fi
done

UNIT_PATH_VALUE="$WRAPPER_DIR:/usr/local/bin:/usr/bin:/bin"

# --- generation directory ---------------------------------------------------------
# A generation directory holds everything the binary reads at startup: the binary and the
# pinned files beside it (rs/src/config.rs pinned_dir prefers the executable's directory).
LIB_DIR="$INSTALL_HOME/.local/lib/codex-sidecar"
GEN_ROOT="$LIB_DIR/generations"
ACTIVATION="$(date -u +%Y%m%dT%H%M%SZ)-$(od -An -N4 -tx1 /dev/urandom | tr -d ' \n')"
GEN_DIR="$GEN_ROOT/$ACTIVATION"
PREVIOUS="$(cat -- "$LIB_DIR/current" 2>/dev/null || true)"

if [ "$ROLLBACK" -eq 1 ]; then
  rb="$(cat -- "$LIB_DIR/previous" 2>/dev/null || true)"
  [ -n "$rb" ] || die "--rollback: no previous generation recorded in $LIB_DIR/previous"
  src_dir="$GEN_ROOT/$rb"
  for f in codex-sidecar preamble.txt thread-config.json; do
    [ -f "$src_dir/$f" ] || die "--rollback: previous generation $rb lacks $f ($src_dir)"
  done
  src_bin="$src_dir/codex-sidecar"
  pinned_src="$src_dir"
  printf 'build   skipped: rollback to generation %s\n' "$rb"
else
  for f in preamble.txt thread-config.json; do
    [ -f "$SCRIPT_DIR/$f" ] || die "missing pinned file $SCRIPT_DIR/$f (copied into the generation directory)"
  done
  pinned_src="$SCRIPT_DIR"
  src_bin="$RUST_BIN"
  if [ -z "$src_bin" ]; then
    command -v cargo >/dev/null 2>&1 || die "cargo not found; needed to build the sidecar"
    cargo build --release --manifest-path "$SCRIPT_DIR/rs/Cargo.toml" >&2 \
      || die "cargo build --release --manifest-path $SCRIPT_DIR/rs/Cargo.toml failed"
    src_bin="$SCRIPT_DIR/rs/target/release/codex-sidecar"
    printf 'build   cargo build --release --manifest-path %s/rs/Cargo.toml\n' "$SCRIPT_DIR"
  else
    printf 'build   skipped: prebuilt %s\n' "$src_bin"
  fi
fi
[ -x "$src_bin" ] || die "rust binary not found or not executable: $src_bin"

mkdir -p -- "$GEN_ROOT"
tmp_gen="$(mktemp -d -- "$GEN_ROOT/.new.XXXXXX")"
cp -- "$src_bin" "$tmp_gen/codex-sidecar"
chmod 0755 -- "$tmp_gen/codex-sidecar"
cp -- "$pinned_src/preamble.txt" "$pinned_src/thread-config.json" "$tmp_gen/"
chmod 0644 -- "$tmp_gen/preamble.txt" "$tmp_gen/thread-config.json"
chmod 0755 -- "$tmp_gen"
mv -T -- "$tmp_gen" "$GEN_DIR"
printf 'gen     %s (activation %s)\n' "$GEN_DIR" "$ACTIVATION"

# --- render the units ---------------------------------------------------------------
UNIT_DIR="$INSTALL_HOME/.config/systemd/user"

# @FLEET_ENV_UNIT@ is the template's sole ordering exception (see its header): rendered as
# After=/Requires=fleet-env-project.service in fleet-env mode, and dropped with --env-file.
if [ -n "$ENV_FILE_ARG" ]; then
  UNIT_ENV_FILE="$ENV_FILE_ARG"
  unit_deps=(-e '/^@FLEET_ENV_UNIT@$/d')
else
  UNIT_ENV_FILE='%t/fleet-env/codex-sidecar.env'
  unit_deps=(-e 's|^@FLEET_ENV_UNIT@$|After=fleet-env-project.service\nRequires=fleet-env-project.service|')
fi

put_unit() { # <name> <content>
  local file="$UNIT_DIR/$1" state
  if [ -f "$file" ] && [ "$2" = "$(cat -- "$file")" ]; then
    state="unchanged"
  else
    if [ -f "$file" ]; then state="updated"; else state="created"; fi
    printf '%s\n' "$2" > "$file"
    chmod 0644 -- "$file"
  fi
  printf 'unit    %s (%s)\n' "$file" "$state"
}

mkdir -p -- "$UNIT_DIR"
put_unit "codex-sidecar@.service" "$(sed \
  "${unit_deps[@]}" \
  -e "s|@ENV_FILE@|$UNIT_ENV_FILE|g" \
  -e "s|@LIB_DIR@|$LIB_DIR|g" \
  -e "s|@PATH@|$UNIT_PATH_VALUE|g" \
  -e "s|@PERSONAS@|$PERSONAS_VALUE|g" \
  -e "s|@RW_PATHS@|$RW_PATHS|g" \
  -- "$TEMPLATE")"
for u in $STATIC_UNITS; do
  [ -f "$SCRIPT_DIR/$u" ] || die "missing unit file: $SCRIPT_DIR/$u"
  put_unit "$u" "$(cat -- "$SCRIPT_DIR/$u")"
done

# --- credentials ------------------------------------------------------------------
if [ -n "$ENV_FILE_ARG" ]; then
  KEY_FILE="$ENV_FILE_ARG"
  printf 'env     %s (user env file, mode 0600; unit EnvironmentFile= points at it)\n' "$ENV_FILE_ARG"
else
  KEY_FILE="$projection"
  printf 'env     %s (fleet-env projection; CODEX_SIDECAR_KEY from the canonical store)\n' "$projection"
fi

# Keep the current and the previous generation (and any still running); drop the rest.
prune() { # <keep...>
  local d name k keep
  for d in "$GEN_ROOT"/*/; do
    [ -d "$d" ] || continue
    name="$(basename -- "$d")"
    keep=0
    for k in "$@"; do [ "$name" != "$k" ] || keep=1; done
    if [ "$keep" -eq 0 ] && [ "$REAL_HOME" -eq 1 ] &&
      systemctl --user is-active --quiet "codex-sidecar@$name.service" 2>/dev/null; then
      keep=1
    fi
    if [ "$keep" -eq 0 ]; then
      rm -rf -- "$d"
      printf 'prune   generation %s\n' "$name"
    fi
  done
  rm -f -- "$LIB_DIR/codex-sidecar" "$LIB_DIR/codex-sidecar.prev" # pre-generation layout
}

record() { # the boot generation and its predecessor
  if [ -n "$PREVIOUS" ] && [ "$PREVIOUS" != "$ACTIVATION" ]; then
    printf '%s\n' "$PREVIOUS" > "$LIB_DIR/previous"
  fi
  printf '%s\n' "$ACTIVATION" > "$LIB_DIR/current"
}

if [ "$REAL_HOME" -ne 1 ]; then
  # A test home never touches systemd: the files above are the whole install.
  record
  prune "$ACTIVATION" "$PREVIOUS"
  printf 'systemd skipped: --home %s is not the current HOME (test render; nothing started, retired or enabled)\n' "$INSTALL_HOME"
  exit 0
fi

# --- live cutover (real home) ----------------------------------------------------------
command -v systemctl >/dev/null 2>&1 || die "systemctl not found"
command -v curl >/dev/null 2>&1 || die "curl not found (the verify reads /healthz)"
sc() { systemctl --user "$@"; }

key="$(sed -n 's/^SIDECAR_KEY=//p' -- "$KEY_FILE" | tail -n 1)"
[ -n "$key" ] || die "SIDECAR_KEY missing from $KEY_FILE"
health() { # body on stdout; empty when unreachable
  curl -sS --max-time 3 -H "authorization: Bearer ${key}" "$HEALTH_URL" 2>/dev/null || true
}

sc daemon-reload
printf 'reload  systemctl --user daemon-reload: done\n'

# The one-time migration from the un-templated unit: it binds 4877 itself, so the socket
# cannot take the address until it stops. This single switch is a stop-then-start.
if [ -f "$UNIT_DIR/$LEGACY_UNIT" ] || sc is-active --quiet "$LEGACY_UNIT" 2>/dev/null; then
  printf 'migrate %s -> codex-sidecar@ generations (stop-then-start: in-flight requests are cut once)\n' "$LEGACY_UNIT"
  sc disable --now "$LEGACY_UNIT" 2>/dev/null || sc stop "$LEGACY_UNIT" || true
  rm -f -- "$UNIT_DIR/$LEGACY_UNIT"
  sc daemon-reload
fi

sc start codex-sidecar-hold.service
sc enable --now codex-sidecar.socket codex-sidecar-docker0.socket
printf 'sockets codex-sidecar.socket codex-sidecar-docker0.socket active\n'

mapfile -t OLD < <(sc list-units --plain --no-legend --state=active,activating,reloading \
  'codex-sidecar@*.service' | awk '{print $1}' | grep -vx "codex-sidecar@$ACTIVATION.service" || true)

# Admission: two generations overlap safely only when both accept the same key.
if [ "${#OLD[@]}" -gt 0 ]; then
  pre="$(curl -sS --max-time 3 -o /dev/null -w '%{http_code}' -H "authorization: Bearer ${key}" "$HEALTH_URL" 2>/dev/null || true)"
  if [ "$pre" = "401" ]; then
    printf 'KEY ROTATION: the running generation refuses the projected SIDECAR_KEY. This switch is a key rotation with a short failure window (requests may fail until the router carries the new key), not a zero-failure cutover.\n' >&2
  fi
fi

NEW_UNIT="codex-sidecar@$ACTIVATION.service"
fail_new() {
  printf 'install.sh: %s; retiring %s, the old generation keeps serving\n' "$1" "$NEW_UNIT" >&2
  sc kill -s SIGUSR1 --kill-whom=main "$NEW_UNIT" 2>/dev/null || sc stop "$NEW_UNIT" 2>/dev/null || true
  rm -rf -- "$GEN_DIR"
  exit 1
}

# Type=notify: `start` returns once the generation's startup checks passed (READY=1).
sc start "$NEW_UNIT" || fail_new "systemctl --user start $NEW_UNIT failed"
verified=0
for _ in $(seq 1 "$VERIFY_TRIES"); do
  body="$(health)"
  case "$body" in
    *'"activation":"'"$ACTIVATION"'"'*)
      case "$body" in *'"status":"ok"'*) verified=1; break ;; esac ;;
  esac
  sleep 0.5
done
[ "$verified" -eq 1 ] || fail_new "verify: /healthz never answered ok from activation $ACTIVATION"
printf 'verify  /healthz answered ok from activation %s\n' "$ACTIVATION"

# The boot generation is the one enabled.
sc enable "$NEW_UNIT" >/dev/null 2>&1
for u in "${OLD[@]+"${OLD[@]}"}"; do sc disable "$u" >/dev/null 2>&1 || true; done
record
printf 'boot    %s enabled\n' "$NEW_UNIT"

rc=0
for u in "${OLD[@]+"${OLD[@]}"}"; do
  sc kill -s SIGUSR1 --kill-whom=main "$u"
  acked=0
  for _ in $(seq 1 "$RETIRE_ACK_TRIES"); do
    if ! sc is-active --quiet "$u" 2>/dev/null; then acked=1; break; fi
    if [ "$(sc show -p StatusText --value "$u" 2>/dev/null)" = "retiring" ]; then acked=1; break; fi
    sleep 0.2
  done
  if [ "$acked" -eq 1 ]; then
    printf 'retire  %s stopped accepting (finishing in-flight requests, then exits 0)\n' "$u"
  else
    printf 'install.sh: %s did not acknowledge SIGUSR1; it may still accept (check sidecar/status.sh)\n' "$u" >&2
    rc=1
  fi
done

prune "$ACTIVATION" "$PREVIOUS"

if command -v loginctl >/dev/null 2>&1 &&
  [ "$(loginctl show-user "${USER:-$(id -un)}" -p Linger --value 2>/dev/null || true)" != "yes" ]; then
  printf 'linger  NOT enabled: the generation will not start at boot (loginctl enable-linger %s)\n' "${USER:-$(id -un)}"
fi
printf 'status  %s/status.sh\n' "$SCRIPT_DIR"
exit "$rc"
